{"code": "const zlib = await import("node:zlib");
const fs = await import("node:fs");
const path = await import("node:path");
const MAGIC = Buffer.from([0x28,0xb5,0x2f,0xfd]);
function decompressAll(buf: Buffer): string {
  const parts: string[] = [];
  const idx: number[] = [];
  let pos = buf.indexOf(MAGIC, 0);
  while (pos >= 0) { idx.push(pos); pos = buf.indexOf(MAGIC, pos + 1); }
  for (let k = 0; k < idx.length; k++) {
    const start = idx[k];
    let end = (k+1 < idx.length) ? idx[k+1] : buf.length;
    for (let tries = 0; tries < 4; tries++) {
      try {
        parts.push((zlib as any).zstdDecompressSync(buf.subarray(start, end)).toString("utf8"));
        break;
      } catch (e) {
        if (k+1+tries < idx.length) end = idx[k+1+tries];
        else if (tries >= 2) break;
        else end = buf.length;
      }
    }
  }
  return parts.join("");
}
const root = "C:\\Users\\Administrator\\.dsh\\sessions\\--D-lean--";
const files: {p:string; size:number; mtime:number; dir:string}[] = [];
for (const d of fs.readdirSync(root)) {
  const f = path.join(root, d, "session.v4.jsonl.zstd");
  if (fs.existsSync(f)) { const st = fs.statSync(f); files.push({p:f, size:st.size, mtime:st.mtimeMs, dir:d}); }
}
files.sort((a,b)=>b.mtime-a.mtime);
const hits: any[] = [];
let scanned = 0, totalChars = 0;
const t0 = Date.now();
for (const f of files) {
  if (Date.now()-f.mtime > 26*3600*1000) break;
  if (Date.now()-t0 > 230000) { console.log("time cap reached"); break; }
  let txt = "";
  try { txt = decompressAll(fs.readFileSync(f.p)); } catch(e) { continue; }
  scanned++; totalChars += txt.length;
  const marks = ["reducedQPilotAnchor", "S1960QPilotAnchor", "S1942PrePsiFive", "# IUT audit ledger"];
  const found = marks.filter(m => txt.includes(m));
  if (found.length > 0) hits.push({dir:f.dir, mtime:new Date(f.mtime).toISOString(), compBytes:f.size, textChars:txt.length, found});
}
console.log("scanned:", scanned, "totalChars:", totalChars, "elapsed ms:", Date.now()-t0);
console.log("hits:", JSON.stringify(hits, null, 1));
", "description": "Scan recent sessions for ledger content markers", "timeoutMs": 300000}

